package dev.nla;
import dev.nla.warehouse.*;import org.springframework.stereotype.Service;import org.springframework.http.HttpStatus;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import java.sql.*;
@Service public class CatalogService {
 private final Store store;private final Adapters adapters;private record Snapshot(long at,List<Map<String,Object>> tables){}private final Map<String,Snapshot> snapshots=new ConcurrentHashMap<>();
 public CatalogService(Store store,Adapters adapters){this.store=store;this.adapters=adapters;}
 public List<Map<String,Object>> discover(String warehouseId,boolean fresh){Map<String,Object> w=store.warehouse(warehouseId);if(Json.str(w,"status").equals("DISABLED"))throw new ApiException(HttpStatus.CONFLICT,"DATASET_UNAVAILABLE","Warehouse đã bị vô hiệu hóa.");Snapshot cached=snapshots.get(warehouseId);if(!fresh&&cached!=null&&System.currentTimeMillis()-cached.at<15000)return cached.tables;
  var adapter=adapters.get(w);try(Connection connection=adapter.connect(w,adapters.password(store.credential(warehouseId)))){Set<String> schemas=new HashSet<>();String schema=Json.str(w,"defaultSchema");if(!schema.isBlank())schemas.add(schema);var tables=adapter.discoverTables(connection,schemas);snapshots.put(warehouseId,new Snapshot(System.currentTimeMillis(),tables));return tables;}catch(SQLException e){org.slf4j.LoggerFactory.getLogger(CatalogService.class).warn("Metadata failure engine={} SQLState={} vendorCode={} type={}",w.get("engine"),e.getSQLState(),e.getErrorCode(),e.getClass().getSimpleName());throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"WAREHOUSE_CONNECTION_ERROR","Không kết nối được warehouse hoặc không đọc được metadata.");}}
 public List<Map<String,Object>> tables(String datasetId){var d=store.dataset(datasetId);Set<String> allowed=new HashSet<>();Json.objects(d.get("allowedTables")).forEach(t->allowed.add(key(t)));var list=discover(Json.str(d,"warehouseId"),false).stream().filter(t->allowed.contains(key(t))).toList();if(list.size()!=allowed.size()){d.put("status","INVALID_SCHEMA");store.updateDataset(d,store.semantic(datasetId));throw new ApiException(HttpStatus.CONFLICT,"SCHEMA_MISMATCH","Bảng được cấu hình không còn tồn tại trong warehouse.");}return list;}
 public List<Map<String,Object>> collection(String datasetId,String kind){var sem=store.semantic(datasetId);if(kind.equals("tables"))return tables(datasetId);if(kind.equals("relationships")){var allowed=tables(datasetId).stream().map(CatalogService::key).collect(java.util.stream.Collectors.toSet());return tables(datasetId).stream().flatMap(t->Json.objects(t.get("foreignKeys")).stream()).filter(rel->allowed.contains(key(Json.map(Json.map(rel.get("to")).get("table"))))).toList();}if(!Set.of("metrics","dimensions","examples").contains(kind))throw ApiException.notFound();return Json.objects(sem.get(kind));}
 public Map<String,Object> context(String datasetId){var sem=new LinkedHashMap<>(store.semantic(datasetId));var physical=tables(datasetId);validateSemantic(sem,physical);sem.put("tables",physical);sem.put("relationships",collection(datasetId,"relationships"));sem.put("referenceTime",java.time.Instant.now().toString());return sem;}
 public void validateSemantic(Map<String,Object> sem,List<Map<String,Object>> tables){Map<String,Set<String>> fields=new HashMap<>();for(var t:tables)fields.put(key(t),Json.objects(t.get("columns")).stream().map(c->Json.str(c,"name")).collect(java.util.stream.Collectors.toSet()));for(var d:Json.objects(sem.get("dimensions")))if(!fields.getOrDefault(key(Json.map(d.get("table"))),Set.of()).contains(Json.str(d,"column")))throw new ApiException(HttpStatus.CONFLICT,"SEMANTIC_MODEL_INVALID","Dimension không khớp metadata vật lý.");Set<String> dimensionNames=Json.objects(sem.get("dimensions")).stream().map(d->Json.str(d,"name")).collect(java.util.stream.Collectors.toSet());for(var m:Json.objects(sem.get("metrics"))){if(Json.objects(m.get("tableRefs")).stream().anyMatch(t->!fields.containsKey(key(t))))throw new ApiException(HttpStatus.CONFLICT,"SEMANTIC_MODEL_INVALID","Metric tham chiếu bảng ngoài dataset.");Object dimensions=m.get("compatibleDimensions");if(!(dimensions instanceof List<?> names)||!dimensionNames.containsAll(names))throw new ApiException(HttpStatus.CONFLICT,"SEMANTIC_MODEL_INVALID","Compatible dimensions không hợp lệ.");String expression=Json.str(m,"expression");try{net.sf.jsqlparser.parser.CCJSqlParserUtil.parseExpression(expression);}catch(Exception e){throw new ApiException(HttpStatus.CONFLICT,"SEMANTIC_MODEL_INVALID","Biểu thức metric không hợp lệ.");}}}
 public Map<String,Object> summary(String id){var d=store.dataset(id);var tables=tables(id);var metrics=collection(id,"metrics");var dims=collection(id,"dimensions");var cats=new TreeMap<String,Long>();tables.forEach(t->cats.merge(Json.str(t,"category"),1L,Long::sum));metrics.forEach(m->{String cat=Json.str(m,"category");if(!cat.isBlank())cats.putIfAbsent(cat,metrics.stream().filter(x->cat.equals(Json.str(x,"category"))).count());});return Json.obj("datasetId",id,"semanticVersion",d.get("semanticVersion"),"schemaVersion",d.get("schemaVersion"),"tableCount",tables.size(),"metricCount",metrics.size(),"dimensionCount",dims.size(),"relationshipCount",collection(id,"relationships").size(),"exampleCount",collection(id,"examples").size(),"categories",cats.entrySet().stream().map(e->Json.obj("name",e.getKey(),"count",e.getValue())).toList());}
 static String key(Map<String,Object> table){return Json.str(table,"schema")+"."+Json.str(table,"name");}
}
